import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve, relative, isAbsolute } from 'node:path';

// Check is strictly read-only: missing or modified managed artifacts fail.
// Callers supply generated bytes, never reconstruct wire fields here.
export async function applyArtifacts(root, artifacts, check = false) {
  const drift = [];
  for (const [name, text] of Object.entries(artifacts)) {
    const path = resolve(root, name);
    const rel = relative(resolve(root), path);
    if (!rel || rel.startsWith('..') || isAbsolute(rel)) throw new Error('Invalid artifact path');
    if (check) {
      let existing;
      try { existing = await readFile(path, 'utf8'); }
      catch (error) { if (error.code !== 'ENOENT') throw error; }
      if (existing !== text) drift.push(name);
    } else {
      await mkdir(dirname(path), { recursive: true });
      await writeFile(path, text);
    }
  }
  if (drift.length) throw new Error(`Contract drift: ${drift.join(', ')}. Regenerate from Go DTOs.`);
}
